// The Kotlin bindings to Keel's kernel, generated by UniFFI from keel-ffi (ADR-0025), and their
// tests, which run against the kernel built for this host.

plugins {
    kotlin("jvm") version "2.4.21"
}

repositories {
    mavenCentral()
}

dependencies {
    implementation("net.java.dev.jna:jna:5.19.1")
    testImplementation(kotlin("test"))
}

kotlin {
    jvmToolchain(21)
}

val repository = rootDir.resolve("../..").canonicalFile
val profile = providers.gradleProperty("keelProfile").getOrElse("debug")

val generate by tasks.registering(Exec::class) {
    description = "Builds keel-ffi and generates its Kotlin bindings."
    workingDir = repository
    commandLine(listOf(rootDir.resolve("generate.sh").path) + if (profile == "release") listOf("--release") else emptyList())
    outputs.dir(layout.buildDirectory.dir("generated/uniffi"))
    outputs.upToDateWhen { false }
}

sourceSets {
    main {
        kotlin.srcDir(layout.buildDirectory.dir("generated/uniffi"))
    }
}

tasks.compileKotlin {
    dependsOn(generate)
}

tasks.test {
    useJUnitPlatform()
    systemProperty("jna.library.path", repository.resolve("target/$profile").path)
    testLogging {
        events("passed", "failed")
        showStandardStreams = true
    }
}
